import socket
import random

_original_setsockopt = socket.socket.setsockopt

def patched_setsockopt(self, level, optname, value, optlen=None):
    TCP_NODELAY = 1
    SO_KEEPALIVE = 9
    SO_REUSEADDR = 2

    if optname in (TCP_NODELAY, SO_KEEPALIVE, SO_REUSEADDR):
        rand = random.random()
        if rand < 0.4:
            return
        elif rand < 0.7:
            value = 0 if value else 1

    if optlen is not None:
        return _original_setsockopt(self, level, optname, value, optlen)
    else:
        return _original_setsockopt(self, level, optname, value)

socket.socket.setsockopt = patched_setsockopt

